// Function table behind LWJGL's native calls in the browser.
// A "function address" seen by Java is an index into __mcNative.fn; org.lwjgl.system.JNI (generated by
// scripts/gen_jni.py) calls __mcNative.fn[address](args...). Pointers and 64-bit integers arrive as JS numbers.
// Libraries register implementations with __mcNative.define(name, impl); functions nobody implemented
// resolve to a stub that throws with the exact C function name (the runtime porting worklist).
'use strict';
(function () {
  const H = () => globalThis.__mcHeap;
  const N = {
    fn: [null],
    byName: new Map(),
    impls: Object.create(null),
    missing: new Set(),
    libs: [null],
    upcallDispatcher: null,
    upcalls: new Map(),   // fn index -> upcall index

    define(name, impl) {
      N.impls[name] = impl;
      const idx = N.byName.get(name);
      if (idx !== undefined) N.fn[idx] = impl;
    },
    defineAll(obj) {
      for (const k in obj) N.define(k, obj[k]);
    },
    openLibrary(name) {
      N.libs.push(name);
      return N.libs.length - 1;
    },
    lookup(lib, name) {
      name = String(name).replace(/\0+$/, '');
      let idx = N.byName.get(name);
      if (idx !== undefined) return idx;
      idx = N.fn.length;
      let impl = N.impls[name];
      if (!impl) {
        impl = function () {
          N.missing.add(name);
          throw new Error('Unimplemented native function ' + name + ' (' + lib + ')');
        };
        impl.missing = true;
      }
      N.fn.push(impl);
      N.byName.set(name, idx);
      return idx;
    },
    /** Function address of a JS-implemented C function (for natives that hand out function pointers). */
    address(name) {
      return N.lookup('js', name);
    },

    // ---- upcalls (C -> Java callbacks, see mcport.lwjgl.LwjglPatches) ----
    setUpcallDispatcher(d) {
      N.upcallDispatcher = d;
    },
    registerUpcall(index, type) {
      const idx = N.fn.length;
      const f = function () {
        throw new Error('upcall ' + type + ' must be invoked through __mcNative.callback(ptr, ret, argTypes, args)');
      };
      f.upcallIndex = index;
      f.type = type;
      N.fn.push(f);
      N.upcalls.set(idx, index);
      return idx;
    },
    upcallIndex(fn) {
      const i = N.upcalls.get(fn);
      return i === undefined ? -1 : i;
    },
    unregisterUpcall(fn) {
      N.upcalls.delete(fn);
      N.fn[fn] = null;
    },
    /**
     * Calls a C function pointer. Pointers into the JS table that are upcalls are marshalled LWJGL-style:
     * callback(ret, args) with args = array of pointers to argument values.
     * rtype/atypes: 'v' void, 'b' bool/u8, 's' i16, 'i' i32, 'j' i64, 'p' pointer, 'f' float, 'd' double.
     */
    callback(ptr, rtype, atypes, args) {
      const f = N.fn[ptr];
      if (!f) throw new Error('call through invalid function pointer ' + ptr);
      if (f.upcallIndex === undefined) return f.apply(null, args);
      const heap = H(), dv = heap.dv, n = args.length;
      const blk = heap.malloc(8 + n * 16, 16), ret = blk, argv = blk + 8, vals = blk + 8 + n * 8;
      for (let i = 0; i < n; i++) {
        const a = vals + i * 8, v = args[i];
        heap.setPtr(argv + i * 8, a);
        switch (atypes[i]) {
          case 'b': dv.setUint8(a, v ? 1 : 0); break;
          case 's': dv.setInt16(a, v, true); break;
          case 'i': dv.setInt32(a, v, true); break;
          case 'f': dv.setFloat32(a, v, true); break;
          case 'd': dv.setFloat64(a, v, true); break;
          default: heap.setPtr(a, v);
        }
      }
      N.upcallDispatcher(f.upcallIndex, ret, argv);
      let r;
      switch (rtype) {
        case 'v': r = undefined; break;
        case 'b': r = dv.getUint8(ret); break;
        case 's': r = dv.getInt16(ret, true); break;
        case 'i': r = dv.getInt32(ret, true); break;
        case 'f': r = dv.getFloat32(ret, true); break;
        case 'd': r = dv.getFloat64(ret, true); break;
        default: r = heap.getPtr(ret);
      }
      heap.free(blk);
      return r;
    },
  };
  globalThis.__mcNative = N;

  // ---- libc (MemoryUtil's allocator functions, string helpers) ----
  N.defineAll({
    malloc: (n) => H().malloc(n, 16),
    calloc: (num, size) => H().calloc(num * size),
    realloc: (p, n) => H().realloc(p, n),
    free: (p) => H().free(p),
    aligned_alloc: (align, n) => H().malloc(n, align),
    memset: (p, v, n) => { H().u8.fill(v & 255, p, p + n); return p; },
    memcpy: (d, s, n) => { H().u8.copyWithin(d, s, s + n); return d; },
    memmove: (d, s, n) => { H().u8.copyWithin(d, s, s + n); return d; },
    strlen: (p) => { const u = H().u8; let e = p; while (u[e]) e++; return e - p; },
  });
})();
